import logging

from SSHLibrary import SSHClient

from .request_forwarder import LocalRequestForwarder, RemoteRequestForwarder
from .exception import CannotEnableServices
from .decorators import exception_handler, timeout

logger = logging.getLogger(__name__)


class FsmServices(object):
    """Class stores methods needed to change state of FSM ports or services available through specific FSM ports.

    .. code-block:: python

        fsm_serv = FsmServices(trs_user='testuser', trs_pass='testpass')
        fsm_serv.enable_ssh()
        fsm_serv.enable_rnd_ports()
    """

    def __init__(self, trs_ip='192.168.255.129', trs_user='Nemuadmin', trs_pass='nemuuser', timeout=None, **kwargs):
        """
        :param string trs_ip:    Transport IP address.
        :param string trs_user:  Transport username.
        :param string trs_pass:  Transport password.
        """
        remote_host = kwargs.get('remote_host', None)
        self._trs_ip = trs_ip
        self._trs_user = trs_user
        self._trs_pass = trs_pass
        if remote_host:
            ssh_client = SSHClient(remote_host, port=22, prompt=kwargs.get('remote_ssh_prompt', '$ '), timeout=timeout)
            self._forwarder = RemoteRequestForwarder(ssh_client, kwargs.get('remote_ssh_user', 'ute'),
                                                     kwargs.get('remote_ssh_pass', 'ute'), trs_ip, trs_user, trs_pass,
                                                     timeout)
        else:
            self._forwarder = LocalRequestForwarder(trs_ip, trs_user, trs_pass, timeout)

    @exception_handler
    @timeout
    def enable_ssh(self, timeout=0, step=0.1):
        """Enable SSH services on FSM."""
        self._execute_http_command('enable_ssh')

    @exception_handler
    @timeout
    def enable_rnd_ports(self, timeout=0, step=0.1):
        """Enable RND services on FSM."""
        self._execute_http_command('enable_rnd_ports')

    @exception_handler
    @timeout
    def disable_ssh(self, timeout=0, step=0.1):
        """Enable SSH services on FSM."""
        self._execute_http_command('disable_ssh')

    @exception_handler
    @timeout
    def disable_rnd_ports(self, timeout=0, step=0.1):
        """Enable RND services on FSM."""
        self._execute_http_command('disable_rnd_ports')

    @exception_handler
    @timeout
    def remove_trs_configuration(self, timeout=0, step=0.1):
        """Remove TRS commissioning."""
        self._execute_http_command('remove_trs_configuration')

    def _execute_http_command(self, command):
        try:
            self._forwarder.send_http_request(command)
            if self._forwarder.token_validation_failed:
                logger.info('Token validation failed. Retrying request with additional tokens.')
                self._forwarder.send_http_request_with_additional_parameters(command)
                if not self._forwarder.request_is_successful:
                    raise CannotEnableServices('Could not resolve failure in token validation.')

        finally:
            self._forwarder.teardown_session()
